files.content:
*,
*::before,
*::after {
  box-sizing: border-box;
}

body {
  display: grid;
  place-items: center;
  min-height: 100vh;
  margin: 0;
  padding: 40px;
  font-family: 'Open Sans', sans-serif;
  font-size: 18px;
  background-color: #6dc1fd;
}

h1 {
  -webkit-text-stroke: 2px #000;
  text-stroke: 2px #000;
  color: transparent;
  font-size: 100px;
  text-align: center;
  text-transform: uppercase;
}
